insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 1, 'What question does the Expert tier ask that neither tier below it asked?', '["Whether the picks that produced the map are correct.", "At a location with no well, how far wrong is the map likely to be?", "Whether a different interpolator would honour the control more exactly.", "How much of the mapped area lies outside the extrapolation limit."]'::jsonb, 1, 'The Associate tier read a crest and a depth at P-1, and the Professional tier read a thickness there. Every one of those numbers is a property of an interpolation and neither tier asked whether the interpolation predicts well.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 2, 'Why is honouring all six wells not evidence that a map predicts well?', '["Because the wells are too few for any statistical claim to be made about them.", "Because the mask hides the part of the map where honouring would be tested.", "Because exact interpolation guarantees it, so several methods honour the same six points.", "Because the spline honours the picks rather than the true horizon, which lies below them."]'::jsonb, 2, 'Honouring is a property the methods share, so it cannot distinguish them. Predictive skill has to be measured by withholding data.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 3, 'Which of the six capstone fields on this tier are graded with no tolerance at all?', '["The cross-validatable count and the live node count.", "The leave-one-out residual and the blind residual.", "The six-well prediction at Ekene-7 and the seven-well crest.", "The cross-validatable count and the leave-one-out residual."]'::jsonb, 0, 'Both are counts, and a count is either right or wrong. The four measured fields carry a 0.1 m tolerance.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 4, 'The tier''s headline is the ratio of its residuals to something. To what?', '["To the 2 m contour interval of the isochore built in the tier below.", "To the 800 m extrapolation limit that defines the mapped area.", "To the 49 m of structural relief across the six picks.", "To the 0.1 m tolerance the capstone allows on the measured fields."]'::jsonb, 2, 'The two residuals are +9.84 m and -5.67 m on a field with 49 m of relief, so a single prediction was wrong by a fifth of the entire structure the map exists to describe.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 5, 'Which false comfort is being offered when a report quotes a zero mean residual at the control wells?', '["The definition of exact interpolation, which would read the same on random numbers.", "A measurement of the map''s accuracy at those wells, which is real but local.", "A demonstration that the picks are internally consistent with each other.", "Evidence that the extrapolation limit has been set conservatively."]'::jsonb, 0, 'An exact interpolator has zero residuals at its own control, always, on any dataset. The reply is to ask for a cross-validation residual at any well the geometry allows.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 6, 'Why do geological-looking contours fail as evidence that a map is good?', '["Because contours are drawn after the fit and cannot represent it faithfully.", "Because a minimum-bending surface produces smooth, plausible shapes from any six numbers.", "Because the contour interval is chosen by a rounding rule that knows nothing about the data.", "Because a geological reader will impose a pattern on any smooth surface."]'::jsonb, 1, 'The Associate tier''s crest is 1.28 m shallower than the shallowest pick and 300 m from it, and it looks entirely geological. Plausibility is produced by the method rather than by the data.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 7, 'Why is withholding a well the only way to create a testable location?', '["Because a test needs a prediction made without the answer, and the answer, at one place.", "Because the mask blanks every location that has not been drilled, so no other point can be sampled.", "Because the spline is exact at the wells and undefined between them.", "Because a location with no well has no truth, and a location with a well has no prediction worth testing."]'::jsonb, 0, 'At the six wells the map knew the answer and between the wells there is no answer. Cross validation manufactures test cases out of a dataset too small to spare any.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 8, 'Why is a leave-one-out residual a pessimistic estimate of the six-well map''s error?', '["Because the withheld well is always the one furthest from the others, which is where any map is weakest.", "Because removing a well shrinks the mask, so the prediction is made close to the edge of the map.", "Because it is measured on a five-well map, which is a different and worse map than the one in use.", "Because the residual is computed as predicted minus actual, which exaggerates errors on a deepening surface."]'::jsonb, 2, 'Going from six wells to five is a 17 percent loss of control, and the Professional tier showed that one well can dominate a third of a map. Pessimistic is the right direction for an error estimate to be biased, and it is worth stating.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 9, 'What is the blind test''s weakness, as against leave-one-out?', '["It is biased pessimistic, because the map that made the prediction had less control.", "It cannot be run at an interior location, so it always measures extrapolation.", "It depends on the frame, since the new well changes the extent of the control.", "There is exactly one of it, it cost a well, and it is available only after the fact."]'::jsonb, 3, 'Leave-one-out is repeatable, available now, biased pessimistic and limited by geometry. The blind test is unbiased, unambiguous, unrepeatable and retrospective.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 10, 'How is a residual defined on this tier, and what does a positive value mean?', '["Actual minus predicted; positive means the map put the horizon too deep.", "Predicted minus actual; positive means the map put the horizon too deep.", "Predicted minus actual; positive means the map put the horizon too shallow.", "The absolute difference between prediction and pick, so the sign carries no meaning."]'::jsonb, 1, 'Depths are positive downward, so a larger predicted number is a deeper predicted horizon. The real horizon is then shallower than the map said.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 11, 'A map predicts 1620 m at a well that finds the horizon at 1608 m. State the residual and read it.', '["Minus 12 m, so the map put the horizon 12 m too shallow.", "Plus 12 m, so the map put the horizon too deep and the real one is shallower.", "Plus 12 m, so the real horizon is 12 m deeper than the map said.", "Minus 12 m, and on a flank that means the mapped closure is smaller than the true one."]'::jsonb, 1, 'Predicted minus actual is 1620 minus 1608. On the flank of a prospect that means the map has understated the structure and the closure is larger than mapped.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 12, 'Which step of the leave-one-out procedure is most easily got wrong?', '["Sampling the reduced surface at the removed well''s coordinates rather than at the nearest node.", "Subtracting the pick from the prediction rather than the other way round.", "Regridding with a frame derived from the reduced control set rather than reusing the full one.", "Removing the well from the map display rather than from the control set."]'::jsonb, 2, 'If the frame moves between runs the residuals measure the frame as well as the interpolation. Derive the frame once from the full control and reuse it for every run.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 13, 'What discipline does the blind test require, and why is it easy to lose?', '["Recording the prediction before the well joins the control, which the instinct to regrid destroys.", "Regridding with the new well before sampling, which is easy to lose because the old map is still on screen.", "Sampling the new well''s location on the reduced five-well map, which is easy to lose because the panel defaults to six wells.", "Widening the mask so the new location is live, which is easy to lose because the default limit is 800 m."]'::jsonb, 0, 'Once the new well is control, the map honours it exactly and the residual is zero by construction. On this field the prediction to record is 1543.3271484375 m at (1500, 1500).'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 14, 'With several residuals available, what does the mean residual measure?', '["Typical error magnitude regardless of direction.", "The largest error the map is likely to make at an untested location.", "The spread of the errors around the map.", "Bias, meaning whether the map reads systematically deep or shallow."]'::jsonb, 3, 'A mean near zero with large individual values means the map is unbiased and imprecise. The mean absolute and the root mean square measure magnitude, the second weighting large errors more heavily.'),
  ('mapping', 'advanced', 'module', 'm01-is-the-map-any-good', 15, 'Which is NOT something this tier does?', '["It measures predictive skill by withholding control.", "It produces a per-location range that can be quoted with a mapped depth.", "It rechecks the isochore work of the tier below on the depth surface.", "It improves the map, by changing the gridding method or adding smoothing."]'::jsonb, 3, 'Nothing here changes the method, the cell size or the mask. Validation measures and does not repair, and no interpolator recovers a feature no control point sampled.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 1, 'Six leave-one-out runs were made on the Ekene control set. What came back?', '["Six residuals, of which one is much larger than the rest.", "Five blanks and one residual, at Ekene-6.", "Three residuals and three blanks, one for each hull vertex removed.", "Six blanks, because the mask refuses to predict at any control location."]'::jsonb, 1, 'Removing Ekene-1 drops the map from 201 live nodes to 144, Ekene-2 to 130 and Ekene-4 to 133, and each of those wells ends up outside the surviving map. Removing Ekene-6 leaves the count at 201.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 2, 'Why does removing Ekene-6 leave the live node count unchanged at 201?', '["Because it is the well nearest the centre of the frame, where the mask is least binding.", "Because its own node is the only one it controls, so only that node is lost.", "Because it is interior to the hull of the other five, so the hull is unchanged.", "Because the remaining five wells are all within 800 m of it, so nothing falls out of reach."]'::jsonb, 2, 'Ekene-6 at (1900, 1800) is not a vertex of the pentagon the other five make. Removing a vertex shrinks the hull past that well''s own location; removing an interior well does not.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 3, 'How many vertices does the convex hull of the six Ekene wells have?', '["Six, since a convex hull always includes every point of the set.", "Four, with Ekene-6 and Ekene-2 both interior.", "Three, which is the minimum for a two-dimensional point set.", "Five, with Ekene-6 the only well not among them."]'::jsonb, 3, 'The vertices are Ekene-5, Ekene-1, Ekene-2, Ekene-4 and Ekene-3. Ekene-6 sits inside the pentagon, which is exactly why it is the only cross-validatable well.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 4, 'Which two tests decide whether the gridder fills a node?', '["Inside the convex hull of the control, and within the extrapolation limit of one of them.", "Inside the frame, and within the extrapolation limit of at least two control points.", "Inside the convex hull, and closer to a control point than the cell size.", "Within the extrapolation limit, and with a fitted value inside the range of the control values."]'::jsonb, 0, 'Both tests use the control point locations only and neither looks at the depth values. That is why the mask of two surfaces gridded from the same wells is identical.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 5, 'Why does widening the extrapolation limit not restore the five missing leave-one-out predictions?', '["Because the limit is already wide enough that every location is within reach of some well.", "Because it relaxes the distance test while the blank is produced by the hull test, which is a hard boundary.", "Because widening the limit also widens the hull, so the withheld well stays outside it.", "Because the engine caps the extrapolation limit at 800 m for masked grids."]'::jsonb, 1, 'No distance setting reaches past the hull. Disabling the hull test instead would produce values by extrapolating outside the control, which measures the spline''s behaviour beyond its data rather than predictive skill.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 6, 'Removing Ekene-2 or Ekene-4 still leaves five hull vertices. Why?', '["Because a convex hull of five points always has five vertices.", "Because those two wells are interior rather than vertices of the six-well hull.", "Because Ekene-6 is promoted onto the boundary when its neighbour leaves.", "Because the hull is recomputed from the frame corners rather than from the wells."]'::jsonb, 2, 'A well that was interior can become a vertex once a neighbour is removed. The live node count is the more direct measurement, and it falls in every vertex-removal case.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 7, 'What is the general rule for which wells can be cross validated?', '["Only wells strictly inside the convex hull of the others.", "Only wells within the extrapolation limit of two or more of the others.", "Only wells that land exactly on a grid node of the shared frame.", "Only wells whose removal leaves the live node count unchanged, which is a coincidence rather than a rule."]'::jsonb, 0, 'A pattern of wells along a single line gives none at all, because every point on a line is a vertex of the degenerate hull. The count grows with interior wells rather than with total wells.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 8, 'A field has nine wells, eight in a ring and one in the middle. How many can be cross validated?', '["Nine, since every well can be removed and the remaining eight regridded.", "Eight, since the ring wells each have neighbours on both sides.", "One, the central well.", "None, because a ring pattern has no strictly interior points."]'::jsonb, 2, 'The eight ring wells are hull vertices. Adding a tenth well between the ring and the centre would make two, which is why an infill programme improves validatability far more than a step-out does.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 9, 'Why would reporting six residuals on this control set be worse than reporting one?', '["Because six residuals take longer to compute and the extra runs add no information.", "Because five of them would be extrapolations, and six numbers invite a reader to treat them as a sample.", "Because the capstone grades the count exactly, so a six would simply be marked wrong.", "Because the five extra residuals would all be smaller, which would flatter the map."]'::jsonb, 1, 'Spline extrapolation diverges quickly, so those five would be large and would be averaged in with the one honest number to produce a headline error that is mostly artefact. A count of one is auditable.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 10, 'What is the leave-one-out residual at Ekene-6 and what does its sign mean?', '["Plus 9.8438720703125 m, so the five-well map put the horizon nearly ten metres too deep.", "Minus 9.8438720703125 m, so the five-well map put the horizon nearly ten metres too shallow.", "Plus 5.6728515625 m, so the five-well map put the horizon five and a half metres too deep.", "Plus 9.8438720703125 m, so the real horizon lies nearly ten metres below the map."]'::jsonb, 0, 'The prediction is 1555.8438720703125 m against a pick of 1546 m. The real horizon is shallower than five wells could see, and the residual is 20 percent of the field''s 49 m of structural relief.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 11, 'Where did the five-well prediction of 1555.84 m at Ekene-6 come from?', '["From Ekene-4 at 1590 m, the nearest well to Ekene-6 once its neighbours are removed.", "From an average of all five remaining picks, which is 1559.2 m.", "From roughly the average of Ekene-3 and Ekene-2, pulled deeper by Ekene-4.", "From the frame origin, since a spline defaults to the mean of its control away from data."]'::jsonb, 2, 'The two nearest remaining wells sit at about 710 m and average 1553 m. The five-well map did something entirely reasonable with the information it had.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 12, 'What is the Ekene-6 residual actually measuring?', '["An error in the gridding, since a better interpolator would have found the culmination.", "An error in the pick at Ekene-6, which is nearly ten metres from the surrounding trend.", "The cost of masking at 800 m, which excluded the nodes that would have carried the high.", "The mismatch between the well spacing and the scale of the structure."]'::jsonb, 3, 'Ekene-6 is a local culmination about 7 m above the level its neighbours imply and roughly 700 m across. Wells 700 to 1000 m apart cannot resolve it, and no interpolator recovers a feature no control point sampled.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 13, 'A colleague proposes smoothing the five-well map with a tension parameter to reduce the residual. What happens?', '["It reduces the residual, because tension pulls the surface toward its control values.", "It probably makes it worse, because tension flattens the surface toward a trend that does not contain the culmination.", "It leaves the residual unchanged, because tension affects only the area outside the hull.", "It reduces the residual at Ekene-6 and increases it everywhere else."]'::jsonb, 1, 'A residual caused by unresolved short-wavelength structure cannot be reduced by changing how the long wavelengths are interpolated. Only new control at the right scale reduces it.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 14, 'Which of these can a single residual support?', '["A bias, since one residual establishes the direction the map errs in.", "A root mean square error for the map, since one value has a magnitude.", "A confidence interval, since the residual bounds the error at that location.", "An order-of-magnitude expectation that a prediction elsewhere is wrong by metres."]'::jsonb, 3, 'It also supports a statement about that location and a lower bound on the map''s error scale. It cannot support a mean, a spread, a bias or an interval.'),
  ('mapping', 'advanced', 'module', 'm02-leave-one-out', 15, 'Two residuals are available: plus 9.84 m and minus 5.67 m. Which summary is the most misleading?', '["The plain mean of plus 2.09 m.", "The mean absolute of 7.76 m.", "The root mean square of 8.03 m.", "Quoting both individually with their signs."]'::jsonb, 0, 'A reader given 2.09 m will conclude the map is good to about two metres, when two large errors of opposite sign have partially cancelled. If a single figure must be quoted, the mean absolute or the root mean square is the honest one.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 1, 'Where is Ekene-7, what did it find, and how far is its nearest control?', '["At (1500, 1500), TOP_SAND at 1549 m, with Ekene-6 500 m away.", "At (1600, 1600), TOP_SAND at 1549 m, with Ekene-6 361 m away.", "At (1500, 1500), TOP_SAND at 1543.33 m, with Ekene-1 707 m away.", "At (1900, 1800), TOP_SAND at 1546 m, with Ekene-3 707 m away."]'::jsonb, 0, 'Three wells sit within 810 m of it and the farthest, Ekene-4, is nearly a kilometre and a half away. The 1543.33 m figure is the prediction rather than the pick.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 2, 'Why does it matter that Ekene-7 was drilled inside the existing pattern rather than as a step-out?', '["Because an interior well is cheaper to drill and the comparison is therefore fairer.", "Because the existing map has a value there, so the test measures interpolation.", "Because an interior well cannot change the crest, which keeps the comparison clean.", "Because a step-out well would have widened the frame and made the two maps incomparable."]'::jsonb, 1, 'A location outside the six-well hull has no mapped value, so the test could not be run at all without disabling the mask. A step-out well tests the concept of the play and only an interior well tests the map.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 3, 'Ekene-7''s pick of 1549 m sits fourth shallowest of the seven. Why is that ordinariness worth noting before the comparison?', '["Because it confirms the map was already close, since an ordinary pick implies a small residual.", "Because it means the well adds no new information and the map will not move.", "Because it removes one explanation: a large residual will not be an exceptional well.", "Because a pick in the middle of the range cannot change the crest or the deepest value."]'::jsonb, 2, 'It is 3 m deeper than Ekene-6 at 500 m and 1 m deeper than Ekene-1 at 707 m, so it sits between its neighbours. The map still missed it by 5.67 m.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 4, 'In which panel state must the six-well prediction at Ekene-7 be read?', '["The six plus Ekene-7 state, since the prediction is a property of the map that contains the well.", "The without Ekene-6 state, since that is the state in which cross validation runs.", "Any state, since the prediction is sampled from the fit rather than from the displayed grid.", "The all six wells state, before Ekene-7 joins the control set."]'::jsonb, 3, 'It is the only state in which the number exists. Once Ekene-7 is control the map honours 1549 m there and the prediction is gone.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 5, 'The six-well prediction at Ekene-7 is 1543.33 m, shallower than Ekene-6 at 1546 m and Ekene-1 at 1548 m. Why can an interpolated value fall outside the range of its nearest wells?', '["Because the fit responds to the whole control set and to its own bending penalty.", "Because bilinear sampling between nodes overshoots wherever the surface is curved.", "Because the mask excludes the nodes nearest to the two deeper wells.", "Because the spline weights control points by inverse distance, which biases toward the shallowest."]'::jsonb, 0, 'The shallow ground at Ekene-3 to the northwest pulls the fitted surface above the level the two nearest wells alone would imply. A minimum-bending surface is not a local average.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 6, 'The map places P-1 at 1542.62 m and Ekene-7, 141 m away, at 1543.33 m. What claim is that making?', '["That the two locations are within the 0.1 m capstone tolerance of each other.", "That the horizon is essentially flat across that gap.", "That P-1 is structurally higher than Ekene-7 by more than the contour interval.", "That the surface between them is unconstrained, since neither location is a well."]'::jsonb, 1, 'A difference of 0.71 m over 141 m is a very flat statement, and the pick at Ekene-7 came in 5.67 m below the map.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 7, 'What is the blind residual at Ekene-7?', '["Plus 5.6728515625 m, so the map put the horizon too deep.", "Minus 5.6728515625 m, so the map put the horizon too shallow at that location.", "Minus 9.8438720703125 m, matching the leave-one-out result in magnitude.", "Zero, because the map honours the new pick exactly once it is added."]'::jsonb, 1, '1543.3271484375 minus 1549 is negative, so the real horizon at Ekene-7 is 5.67 m deeper than the map said. A zero would mean the prediction was read after the well joined the control.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 8, 'Which qualifier makes the blind residual different in kind from the leave-one-out residual?', '["It is measured at a location closer to control, so it should be smaller.", "It carries no pessimistic bias, being measured on the map in use.", "It is measured on a map with more wells, so its tolerance is tighter.", "It is measured at an interior location, which the leave-one-out test cannot reach."]'::jsonb, 1, 'Leave-one-out measures a five-well map, which is a different and worse map than the one in use. Both tests here are at interior locations.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 9, 'Put the two residuals side by side. What is the pattern?', '["The blind residual is larger, at a location further from control, on a better constrained map.", "The blind residual is smaller because the capstone grades it to a tighter tolerance.", "The two are equal in magnitude and opposite in sign, which is what makes them cancel.", "The blind residual is smaller, at a location closer to control, on a better constrained map."]'::jsonb, 3, 'Plus 9.84 m at 707 m from control on a five-well map, against minus 5.67 m at 500 m from control on a six-well map. It is smaller and it is not small.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 10, 'A prospect is being ranked on a mapped closure of 8 m. What does the blind residual say about that ranking?', '["That the closure should be reduced by 5.67 m before the ranking is made.", "That the ranking is safe, because a residual at one location does not transfer to another.", "That the prospect should be abandoned, since the error exceeds most of the closure.", "That the closure sits within the demonstrated error, so it is not sufficient evidence."]'::jsonb, 3, 'A map that was wrong by 5.67 m where it could be checked cannot distinguish an 8 m closure from no closure with confidence. That calls for more control or an independent constraint rather than for abandoning the prospect.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 11, 'What would two same-signed residuals have suggested?', '["Something systematic: a datum error, a pick bias, or a missed trend.", "Something local: structure at a scale shorter than the well spacing.", "That the two tests were run on the same control set by mistake.", "That the interpolator is exact at its control, which produces consistent signs."]'::jsonb, 0, 'Each of those has a specific and cheap chase: check the datums, re-pick two wells blind, or fit a trend before gridding the residual. None of them requires new data.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 12, 'What do two opposite-signed residuals at interior locations 500 m apart indicate?', '["That one of the two was computed with predicted and actual the wrong way round.", "That the map is unbiased, since the errors average close to zero.", "That local structure the control does not resolve is smoothed by the interpolator.", "That the two tests measure different quantities and should not be compared."]'::jsonb, 2, 'A systematic effect does not reverse sign between two nearby interior locations. This is a genuine finding from a sample of two, and it is the only one.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 13, 'Why does the local rather than systematic reading change what would improve the map?', '["Because a local error is smaller and therefore not worth correcting.", "Because local errors are removed by refining the cell size, which costs nothing.", "Because a systematic fix is cheap while a local one needs more control.", "Because a local error can be absorbed into the extrapolation limit."]'::jsonb, 2, 'Knowing the fix is expensive before proposing it is worth something. It also rules out a constant shift, which would improve one location and worsen the other by the same amount.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 14, 'A colleague proposes shifting the map down by 2.09 m to remove the apparent bias. What happens to the residuals?', '["The Ekene-6 residual becomes 11.93 m and the Ekene-7 residual minus 3.58 m.", "Both shrink by 2.09 m, which is why the shift is worth applying.", "Both grow, because a shift in either direction adds to one error and to the other.", "The residuals are unaffected, because a constant shift moves the control points too."]'::jsonb, 0, 'Shifting a map to remove a mean of opposite-signed residuals moves error around without removing any. It is only worth doing when the residuals share a sign.'),
  ('mapping', 'advanced', 'module', 'm03-the-blind-test', 15, 'Which comparison is the uncomfortable one on this field?', '["The 9.84 m residual against the 49 m of structural relief, which is 20 percent.", "The 5.67 m residual against the 0.1 m capstone tolerance.", "The 2.9 m mapped position of P-1 below the crest against residuals of 5.67 and 9.84 m.", "The 201 live nodes against the 500 nodes of the full frame."]'::jsonb, 2, 'The prospect''s mapped position relative to the crest is smaller than either measured error. That is the row that decides what the map can be used for.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 1, 'With Ekene-7 added to the control, what happens to the live node count?', '["It rises to 260, because the hull now extends to include the new well.", "It stays at 201, because Ekene-7 is interior and adds no hull area.", "It rises slightly, because nodes within 800 m of the new well become reachable.", "It falls, because a seventh control point tightens the hull around the pattern."]'::jsonb, 1, 'Every node within 800 m of Ekene-7 was already within 800 m of something. The field is graded exactly, and a learner expecting the count to rise is expecting an exterior well.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 2, 'The cross-validatable count rises from 1 to 2 when Ekene-7 joins. Why?', '["Because the control set is larger, and the count rises with the number of wells.", "Because the hull gains a vertex, which makes Ekene-6 interior for the first time.", "Because an interior well was added, and both Ekene-6 and Ekene-7 sit inside the hull.", "Because the live node count is unchanged, which is the test for cross-validatability."]'::jsonb, 2, 'The count grows with interior wells rather than with total wells. An exterior appraisal well would have left it at 1.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 3, 'Why does the seven-well leave-one-out at Ekene-7 reproduce the blind residual exactly?', '["Because removing Ekene-7 restores the original six wells, so it is the same calculation.", "Because the spline honours Ekene-7 exactly, so its residual is zero either way.", "Because both tests are graded to 0.1 m, which is wider than the difference between them.", "Because the frame is unchanged between the two runs, which forces the two answers to agree."]'::jsonb, 0, 'It is a useful consistency check on the whole procedure: the frame, the settings, the sampling and the removal logic all have to be right for the identity to hold at minus 5.6728515625 m.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 4, 'Ekene-6''s leave-one-out residual moves from plus 9.8439 m to plus 9.8157 m when Ekene-7 joins the control. What does a change of 0.028 m say?', '["That the new well corrected most of the error at Ekene-6, since the residual fell.", "That the two runs used different frames, since a genuine change would be larger.", "That the new well added almost no information at Ekene-6, 500 m away.", "That the residual is dominated by the pick at Ekene-6 rather than by the map."]'::jsonb, 2, 'Ekene-7''s pick of 1549 m is close to what the surrounding wells already implied, and its influence 500 m away is small. A well fixes the map where it is, and its influence falls off quickly.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 5, 'What does an interior appraisal well buy, according to this module?', '["Coverage, resolution across the field, and a measurement at its own location.", "A measurement at its own location, a small improvement nearby, and one more testable point.", "A wider mask, a finer contour interval, and a lower jackknife spread everywhere.", "A correction to the existing picks and a reduction in the crest overshoot everywhere."]'::jsonb, 1, 'It does not buy coverage and it does not buy resolution across the field. The de-risking is local, with a radius of roughly the scale over which the surface actually varies.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 6, 'How would the picture differ if Ekene-7 had been drilled at (3000, 1000), outside the hull?', '["The live node count would rise and the cross-validatable count would stay at 1.", "Both counts would rise, since an exterior well extends the hull and can itself be dropped.", "Neither count would change, since the mask is computed from the frame rather than the control.", "The live count would stay at 201 and the cross-validatable count would rise to 2."]'::jsonb, 0, 'An exterior well is a hull vertex, so it cannot be dropped and predicted, and the blind test there would have been an extrapolation. An exterior well buys coverage and an interior well buys validatability.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 7, 'Differencing the six-well and seven-well maps, where is the largest change and what is it equal to?', '["At the crest, and it equals the reduction in the spline overshoot.", "At P-1, and it equals 79 percent of the blind residual.", "At Ekene-7''s own node, and it equals the blind residual.", "At Ekene-6, and it equals the difference between the two leave-one-out residuals."]'::jsonb, 2, 'The map said 1543.3271484375 m there and now honours 1549 m, a change of 5.6728515625 m. An exact interpolator must move the surface through the new point, so the distance it travels is the error it was making.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 8, 'What piece of foresight follows from the largest change equalling the blind residual?', '["The change at a new well''s own location is knowable from the pick and the prediction.", "The mean absolute change across the map can be predicted from the residual and the well count.", "The direction in which the crest will move can be read from the sign of the residual.", "The new well''s influence radius can be computed from the size of the residual."]'::jsonb, 0, 'Subtract the prediction from the pick and you have the movement at that node. Nothing else about the difference map is knowable in advance.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 9, 'The mean absolute change over the 201 live nodes is 1.919145119130908 m. Why is it so large for one well?', '["Because the new well sits near the centre of the map, where most of the nodes are.", "Because a thin-plate spline is not local and six is a small control set.", "Because the difference is computed before the mask is applied, so edge nodes dominate it.", "Because the frame was rederived with the new well, which shifted every node slightly."]'::jsonb, 1, 'Every control point contributes everywhere, with an influence that falls off slowly. On a field with fifty wells one more would move the mean node by centimetres.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 10, 'What does a mean absolute change of 1.92 m on a field with 49 m of relief measure?', '["The error of the seven-well map, which is now known to about two metres.", "The size of the spline overshoot that the new well removed.", "How much of the six-well map was assumption rather than data.", "The typical thickness of a contour band on the six-well map."]'::jsonb, 2, 'About four percent of the total relief was rearranged by a single well. It is not an estimate or a model: the map changed by that much when one more fact arrived.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 11, 'What is the crest of the seven-well map, and how did it move?', '["1540.70556640625 m at (1400, 2200), 0.9874 m deeper and 200 m north.", "1539.7181396484375 m at (1400, 2000), unchanged, because the crest is a control value.", "1540.70556640625 m at (1500, 1500), which is Ekene-7''s own node.", "1541 m at Ekene-3, because the new well removed the overshoot entirely."]'::jsonb, 0, 'The deepest point did not move at all, because 1590 m is Ekene-4''s own pick and an exact interpolator does not move a control point.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 12, 'The crest overshoot against the shallowest pick falls from 1.2819 m to 0.2944 m. What does that establish?', '["That the overshoot was a display artefact that a finer grid would also have removed.", "That spline overshoot is an information deficit, and it shrinks when control is added near it.", "That the shallowest pick at Ekene-3 was 1 m too deep and has now been corrected.", "That an exact interpolator stops overshooting once it has seven control points."]'::jsonb, 1, 'The Associate tier could describe the overshoot and could not remove it, since refining the cell and changing the limit both leave it. Ekene-7 put a measurement into the gap the spline was filling with curvature.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 13, 'Which well would most reduce the uncertainty on a mapped crest that is a spline overshoot?', '["One drilled on the crest itself, which converts the overshoot into a measurement.", "One drilled outside the hull, which extends the mask and constrains the flank.", "None, because overshoot is a property of the interpolator and is unaffected by control.", "One drilled between the crest and its nearest control, removing the room to curve."]'::jsonb, 3, 'Ekene-7 sits about 510 m from the old crest node and cut the overshoot by 77 percent. A well on the crest would also help, and it is a more expensive way to learn the same thing.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 14, 'How much did P-1 move when Ekene-7 joined the control, and why so much?', '["By 0.71 m, the difference the six-well map showed between P-1 and Ekene-7.", "By 5.6729 m, the full blind residual, since P-1 and Ekene-7 are both interior.", "By 0.9874 m deeper, the same amount the crest moved.", "By 4.4854 m deeper, taking 79 percent of the change at Ekene-7''s node."]'::jsonb, 3, 'The influence of a new control point is strongest at its own location and falls off with distance, and 141 m on a field with 700 m well spacing is very close. P-1 goes from 2.90 m below the crest to 6.40 m below it.'),
  ('mapping', 'advanced', 'module', 'm04-what-the-new-well-changed', 15, 'Adding Ekene-7 changed the contour interval from 10 m to 5 m. Why?', '["Because the mask was recomputed with the new well, which changed the range of live values.", "Because seven control points allow a finer interval than six, which the rule accounts for.", "Because the crest moved deeper, which compressed the upper contours into a smaller band.", "Because the range fell from 50.28 m to 49.29 m and crossed the threshold where a tenth of it drops below 5."]'::jsonb, 3, 'A change of less than two percent in the range landed on the one threshold in the scale that doubles the number of lines. The seven-well map looks nearly twice as resolved and none of the extra detail is real.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 1, 'How does the jackknife differ from leave-one-out?', '["It removes two wells at a time rather than one, which doubles the number of runs available.", "It samples a fixed location of interest under each removal, not the removed well.", "It removes wells at random rather than in turn, which makes the spread a genuine sample.", "It regrids at three cell sizes rather than one, and reports the spread across them."]'::jsonb, 1, 'Leave-one-out asks how wrong the map was at the well removed. The jackknife asks how much the answer at the location you care about depends on which wells you have.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 2, 'Why can the jackknife be run for all six wells when leave-one-out could not?', '["Because P-1 is deep in the interior and stays live under every removal.", "Because the jackknife disables the hull mask, which is acceptable when no residual is computed.", "Because the jackknife uses the seven-well control set, in which more wells are interior.", "Because removing a well does not change the hull when the sampled location is not a well."]'::jsonb, 0, 'Removing Ekene-1 puts Ekene-1''s own site outside the mask, but it does not put P-1 outside it. The hull limitation applies to the sampled location, not to the removed well.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 3, 'Which single removal moves the mapped depth at P-1 the most, and by how much?', '["Ekene-4, by 4.59 m, because it is the deepest well on the field.", "Ekene-3, by 1.19 m, because it carries the shallowest pick.", "Ekene-2, by 0.68 m, because it is the well the map cannot sample at its own location.", "Ekene-6, by 7.09 m, because it is the nearest control at 361 m."]'::jsonb, 3, 'P-1 moves from 1542.6199 m to 1549.7084 m without Ekene-6. It is the only interior well and the nearest control for a third of the map.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 4, 'Ekene-4 is 1345 m from P-1 and its removal still moves the answer by 4.59 m. Why?', '["Because it is the deepest well by 25 m and sits alone in the northeast.", "Because it is a hull vertex, and removing a vertex always has a large effect.", "Because its removal shrinks the mask, so P-1 is sampled from a different set of nodes.", "Because the spline weights distant control more heavily than near control."]'::jsonb, 0, 'The dominant wells are the nearest ones plus any well that anchors an extreme. Both categories matter and only the first is obvious.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 5, 'What is the jackknife spread at P-1?', '["3.12 m, the standard deviation of the six values.", "7.7691650390625 m, from 1541.939208984375 to 1549.7083740234375 m.", "4.4854 m, the movement caused by the seventh well.", "15.51 m, the sum of the absolute residuals from the two validation tests."]'::jsonb, 1, 'The full range is the easiest to explain and the most conservative summary. The standard deviation of 3.12 m is the one to use if the number is going into a probabilistic calculation.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 6, 'The six five-well maps centre on 1544.66 m against the six-well answer of 1542.62 m. Should the estimate be moved there?', '["Yes, because the mean of six recomputations is a better estimate than a single run.", "Yes, but only if the six values are weighted by how much control each removal lost.", "No, because each of the six comes from a map with less data than the one in use.", "No, because the difference of 2.04 m is inside the jackknife spread and therefore not significant."]'::jsonb, 2, 'The jackknife supplies a spread around the six-well answer, not a correction to it. The best estimate from six wells remains the six-well map.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 7, 'What exactly does the jackknife spread measure?', '["The total uncertainty on the mapped depth at that location.", "The map''s predictive skill, measured where the truth is known.", "Sensitivity to control: how much the answer moves if any single well did not exist.", "The range of depths consistent with the picks within their measurement error."]'::jsonb, 2, 'It is a good proxy for error on sparse control, because the dominant source of error at an interior location on a six-well map is that six wells do not determine the surface. Pick, datum, depth conversion and method uncertainty are all absent from it.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 8, 'Four numbers on this field are 9.84, 5.67, 7.77 and 4.49 m. What is the point of putting them side by side?', '["They are four independent routes to the same order of magnitude.", "They average to about 7 m, which is the field''s error bar.", "Their spread of 5.35 m measures the disagreement between the validation methods.", "They show that the jackknife is the most conservative of the four techniques."]'::jsonb, 0, 'A leave-one-out residual, a blind residual, a jackknife spread and the movement caused by a new well all land between 4.5 and 10 m. A single number of that order would be easy to dismiss as a one-off.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 9, 'The seven-well map reads 1547.105224609375 m at P-1. What does that establish about the jackknife?', '["That the jackknife range was too wide, since the actual movement was smaller than the spread.", "That the range computed from six wells contained the effect of adding a seventh, at 66.5 percent of its width.", "That the jackknife mean of 1544.66 m was the better estimate all along.", "That the spread should be recomputed on seven wells before it is quoted again."]'::jsonb, 1, 'The move could have landed outside the range, been negligible, or landed at its very edge. It was a substantial 4.49 m comfortably inside a range that was neither too tight nor absurdly wide.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 10, 'Which two numbers had to be recorded before Ekene-7 was drilled for the tier''s checks to be possible?', '["The crest and the live node count of the six-well map.", "The leave-one-out residual at Ekene-6 and the jackknife standard deviation.", "The six-well prediction at Ekene-7 and the jackknife range at P-1.", "The mapped thickness at P-1 and the well mean of the six thicknesses."]'::jsonb, 2, 'Neither is recoverable once the seventh well is in the control set, because the map that produced them no longer exists. Writing them down is the whole discipline and it costs one line.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 11, 'Why is the jackknife range not a confidence interval?', '["Because it was computed from a map rather than from measurements.", "Because six values from removing one well each are not independent samples.", "Because the range is asymmetric, and a confidence interval must be symmetric.", "Because six values are too few, though thirty would produce a genuine interval."]'::jsonb, 1, 'They are six deterministic recomputations sharing five wells out of six with each other, so nothing in the construction produces a frequency. Say that the answer moves over a range of 7.77 m if any single well is removed.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 12, 'Why should the jackknife range not be quoted as 1542.62 plus or minus 3.9 m?', '["Because the range is 7.77 m wide and half of it is 3.89 m, which rounds badly.", "Because a plus-or-minus implies a probability that the construction does not produce.", "Because the six-well answer sits 0.68 m above the bottom of the range and 7.09 m below the top.", "Because the range should be quoted at one standard deviation, which is 3.12 m."]'::jsonb, 2, 'The removals overwhelmingly push the answer deeper, because the wells that dominate at P-1 are pulling the surface up. Halving the range throws that asymmetry away.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 13, 'Which contribution is NOT inside the jackknife spread?', '["The effect of removing the nearest control point.", "The effect of removing the well that anchors the deepest corner.", "The sensitivity of the answer to which six wells were drilled.", "Pick uncertainty in the TOP_SAND picks themselves."]'::jsonb, 3, 'The jackknife holds the picks, the datum, the depth conversion and the method fixed. It is one term in an uncertainty budget, and on sparse control it is usually the largest.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 14, 'Why is a single jackknife number meaningless when quoted for a whole map?', '["Because it is a per-location quantity and would be close to zero at a control point.", "Because it changes with the cell size, so it cannot be quoted without one.", "Because it is computed from five-well maps, which do not cover the whole area.", "Because the mask changes under each removal, so no two locations share a control set."]'::jsonb, 0, 'At a well every five-well map still honours the remaining wells and the surface is pinned. It must be computed at the location the decision is about.'),
  ('mapping', 'advanced', 'module', 'm05-an-uncertainty-you-can-quote', 15, 'Which of these is the reporting line this tier asks for?', '["P-1: 1542.62 m.", "P-1: 1542.619873046875 m, thin-plate spline, 25 by 20 grid at 100 m, two-cell pad, 800 m limit, contoured at 10 m, 201 live nodes, crest 1539.7181396484375 m.", "P-1: 1542.6 plus or minus 3.9 m at 90 percent confidence, from a six-well thin-plate spline.", "P-1: 1542.6 m from six wells (thin-plate spline, 100 m cell, 800 m limit); one-well jackknife 1541.9 to 1549.7 m, dominated by Ekene-6 at 361 m; interior validation errors plus 9.8 m and minus 5.7 m."]'::jsonb, 3, 'The four elements are the number rounded honestly, the conditions needed to reproduce it, the control sensitivity with its dominant well named, and the demonstrated errors quoted individually rather than averaged.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 1, 'Which step of the validation workflow comes before any residual is computed?', '["Running the jackknife at every location a decision depends on.", "Identifying which wells are interior to the control hull.", "Recording the current map''s prediction at any planned well location.", "Differencing the old and new maps once a well arrives."]'::jsonb, 1, 'That count is the number of wells you can cross validate, and it is usually much smaller than the well count. Doing it first tells you how much validation is available before any is attempted.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 2, 'Which step costs nothing and is most often skipped?', '["Freezing the map before any validation run.", "Recording the prediction at a planned well.", "Reporting residuals individually rather than averaged.", "Running leave-one-out at every interior well."]'::jsonb, 1, 'It has to be done at a moment when nothing appears to be happening. Building it into the well proposal solves it, since the proposal is written well before the well is spudded.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 3, 'Why must every validation run use the same frame?', '["Because the residuals compare values at fixed coordinates, so a moving lattice pollutes them.", "Because the gridder caches the frame between runs and a change invalidates the cache.", "Because a frame derived from five wells covers less area, so some residuals would be blank.", "Because the capstone grades the live node count, which depends on the frame."]'::jsonb, 0, 'Every run must differ from the others in exactly one thing, the control set. On Ekene three of the six five-well subsets derive a different frame if you let them.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 4, 'What is wrong with running the validation after the map has been presented?', '["The residuals change, because a presented map is usually smoothed for display.", "The frame is no longer available, since presentation exports a contoured image.", "It becomes an audit nobody wants to fail rather than a measurement that informs.", "Nothing, provided the same frame and settings are used for both."]'::jsonb, 2, 'A jackknife spread of 7.77 m arriving after a prospect has been ranked on a 2.9 m difference from the crest is the same arithmetic and a much harder conversation. Validation belongs with the map, in the same document.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 5, 'A field has twelve wells, three of them interior, and a prospect is being ranked. Which product of the workflow informs the ranking today?', '["The three leave-one-out residuals, which are enough to look for a common sign.", "The recorded prediction at the proposed well, which becomes a residual in a few months.", "The jackknife at the prospect, with twelve values and a tighter spread than Ekene''s.", "The difference map between the current and previous vintages."]'::jsonb, 2, 'It is available immediately and it is a per-location quantity, so it speaks to the ranking directly. Removing one of twelve wells is a smaller perturbation than removing one of six.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 6, 'A residual of exactly zero comes back at a withheld well. What does it mean?', '["That the map predicted that well perfectly, which is a good result on sparse control.", "That the well was never actually removed from the control set.", "That the withheld well landed exactly on a grid node, where sampling is exact.", "That the prediction was blanked by the mask and reported as zero."]'::jsonb, 1, 'An exactly interpolating method returns its control value at its own control, always. A zero is a red flag and the run has to be repeated.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 7, 'Which check confirms that the baseline you are validating is the map in use?', '["Confirming that the full-control run reproduces the crest and P-1 of the map in use.", "Confirming that the live node count is 201 under every leave-one-out run.", "Confirming that the residual at the withheld well is non-zero.", "Confirming that the two residuals have opposite signs."]'::jsonb, 0, 'If the baseline does not match the map in use, nothing computed from it applies to that map. It is one of the three setup checks, with one frame and identical settings.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 8, 'Which end-to-end test does the seven-well leave-one-out at Ekene-7 provide?', '["It confirms that the mask is disabled, since a value comes back at a hull vertex.", "It confirms the pick at Ekene-7, since the residual reproduces the drilled depth.", "It must reproduce the blind residual exactly, which needs frame, settings and removal logic to agree.", "It measures how much the seventh well improved the map, which is the difference between the two residuals."]'::jsonb, 2, 'Removing Ekene-7 from the seven-well set restores the original six wells, so the identity must hold. A disagreement of any size means something in the pipeline differs between the two paths.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 9, 'A report quotes six residuals with a root mean square of 3.1 m on a six-well field. What is wrong?', '["The root mean square, which should be quoted as a mean absolute on so few values.", "The count: a six-well field cannot have six cross-validatable wells.", "The mean of minus 0.2 m, which suggests a bias that six residuals cannot establish.", "Nothing, provided every run used the same frame and settings."]'::jsonb, 1, 'The hull of any point set has at least three vertices. So at least three of the six residuals are extrapolations, the mask was disabled or absent, and the summary statistics are dominated by numbers the map would never be asked to produce.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 10, 'Which capstone field must be read first, and why?', '["The live node count with Ekene-7 included, because it fixes which panel state the others came from.", "The cross-validatable count, because it decides whether any other field can be reported.", "The six-well prediction at Ekene-7, because adding the well destroys it.", "The leave-one-out residual at Ekene-6, because it is the only one that needs a reduced control set."]'::jsonb, 2, 'Once Ekene-7 is in the control set the map honours 1549 m at that location and the prediction ceases to exist anywhere. It is read in the all-six-wells state, at 1543.3271484375 m.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 11, 'Which panel state gives the crest and the live node count that the capstone grades?', '["All six wells.", "Without Ekene-6.", "Without Ekene-4, the deepest well.", "Six plus Ekene-7."]'::jsonb, 3, 'The crest reads 1540.70556640625 m and the live count 201 in that state. Reading the crest from the six-well state gives 1539.7181 m, which is ten times the 0.1 m tolerance away.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 12, 'Which self-consistency check catches a learner who computed residuals as actual minus predicted?', '["The seven-well crest must be deeper than the six-well crest.", "The live count with Ekene-7 must equal the six-well live count.", "The prediction at Ekene-7 minus 1549 must equal the blind residual.", "The Ekene-6 residual must be positive and the Ekene-7 residual negative."]'::jsonb, 3, 'Both signs flip, so both fields fail against a 0.1 m tolerance by 19.7 m and 11.3 m. The last check catches an inconsistent pair rather than a flipped one.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 13, 'A learner submits 1, plus 9.84, 1549, 0, 1540.71 and 201. What happened?', '["The panel was switched to the seven-well state before the prediction was read.", "The mask was disabled, so an extrapolated prediction was reported.", "The residuals were computed as actual minus predicted.", "The crest was read from the six-well state rather than the seven-well one."]'::jsonb, 0, 'The submitted prediction is Ekene-7''s actual pick and the residual of zero follows from it. Four of six fields pass, and the two that fail are exactly the two the blind test consists of.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 14, 'What can mapping guarantee, uniquely at this tier?', '["That the picks feeding the map are correct at every well.", "That a cross-validation residual is available at every well in the pattern.", "That the mapped depth at a prospect is within the jackknife range of the truth.", "A measured statement about predictive skill wherever the geometry allows one, with an honest count of how many are available."]'::jsonb, 3, 'It can also guarantee exact honouring, honest blanks, reproducibility and node-for-node consistency of combinations. Whether the picks are right belongs to well correlation.'),
  ('mapping', 'advanced', 'module', 'm06-the-validation-workflow', 15, 'Which is one of the three habits the Mapping ladder ends on?', '["Attach a range to every number that leaves your desk.", "Refine the cell size until the mapped extremes settle onto control values.", "Grid every surface at the finest cell the control will support.", "Quote a root mean square residual whenever more than one is available."]'::jsonb, 0, 'The other two are to withhold something, since a map validated against its own control has not been validated, and to count what you can honestly test and report the count.'),
  ('mapping', 'advanced', 'final', null, 1, 'Which set of six values is the Ekene validation capstone answer key?', '["1, plus 9.8438720703125, 1543.3271484375, minus 5.6728515625, 1540.70556640625 and 201.", "6, plus 9.8438720703125, 1543.3271484375, minus 5.6728515625, 1539.7181396484375 and 201.", "1, minus 9.8438720703125, 1549, plus 5.6728515625, 1540.70556640625 and 260.", "2, plus 9.815673828125, 1543.3271484375, minus 5.6728515625, 1540.70556640625 and 201."]'::jsonb, 0, 'The last option is the seven-well leave-one-out figures, which are correct numbers for a different question. The cross-validatable count on the six-well set is 1 and the crest is read with Ekene-7 included.'),
  ('mapping', 'advanced', 'final', null, 2, 'What is the single reason five of the six leave-one-out runs return no prediction?', '["The extrapolation limit of 800 m does not reach the removed well from the remaining control.", "Those five wells are hull vertices, so removing one puts its site outside the rest.", "The five-well spline is unstable and the engine refuses to report a value.", "Those five wells do not land on grid nodes, so no value can be sampled at them."]'::jsonb, 1, 'Both mask tests use control locations only. Removing a vertex shrinks the polygon past the removed well; removing the interior well leaves it unchanged.'),
  ('mapping', 'advanced', 'final', null, 3, 'A validation report states that all nine wells on a nine-well field were cross validated. What does that tell you?', '["That the field has an unusually favourable well geometry.", "That the hull mask was disabled.", "That the report used the jackknife rather than leave-one-out.", "That the wells were gridded on a frame derived per subset."]'::jsonb, 1, 'A hull has at least three vertices and a vertex cannot be interior to the rest. Any report of a full-count cross validation has produced numbers the map would never be asked for.'),
  ('mapping', 'advanced', 'final', null, 4, 'Which change to a well programme most improves how much cross validation is available?', '["Drilling step-out wells, which extend the mapped area.", "Drilling infill wells inside the existing pattern.", "Widening the extrapolation limit on the existing control.", "Refining the grid to a 50 m cell so more nodes are tested."]'::jsonb, 1, 'The count grows with interior wells rather than with total wells. Adding Ekene-7 inside the pattern took Ekene''s count from 1 to 2.'),
  ('mapping', 'advanced', 'final', null, 5, 'The leave-one-out residual at Ekene-6 is unchanged at 50 m and 100 m cells and moves by 0.16 m at 200 m. What does that establish?', '["That the residual is a property of the geometry and the interpolator.", "That the capstone tolerance of 0.1 m is too tight for a 200 m cell.", "That the residual would vanish at a fine enough cell size.", "That node placement is the dominant source of error in the residual."]'::jsonb, 0, 'It is also unchanged at 800, 1200 and 2000 m extrapolation limits, and goes blank at 400 m when the mask no longer reaches. That stability is what makes it worth quoting.'),
  ('mapping', 'advanced', 'final', null, 6, 'Why was the five-well prediction of 1555.84 m at Ekene-6 reasonable?', '["Because it lies between the shallowest and deepest picks on the field.", "Because it sits near the average of the two nearest wells, pulled deeper by Ekene-4.", "Because a minimum-bending surface always predicts the mean of its control away from data.", "Because it honours Ekene-3 and Ekene-2 exactly, which are the nearest control points."]'::jsonb, 1, 'Ekene-3 at 1541 m and Ekene-2 at 1565 m are almost equidistant at about 710 m and average 1553 m. The map did the right thing with the information it had.'),
  ('mapping', 'advanced', 'final', null, 7, 'What is the Ekene-6 residual measuring, at bottom?', '["The bending energy penalty the thin-plate spline applies between control points.", "The extrapolation error of a five-well map at a location on its boundary.", "The mismatch between the well spacing and the scale of the structure.", "The difference between a five-well map and a six-well map at a single node."]'::jsonb, 2, 'Ekene-6 is a local high none of the five can see. No interpolator recovers a feature no control point sampled, so the response that would help is more control rather than a better method.'),
  ('mapping', 'advanced', 'final', null, 8, 'Which statement about the blind test is correct?', '["It is biased pessimistic, since the map used had one fewer well than the map in use.", "It measures the map actually in use, so it carries no pessimistic bias.", "It can be repeated at any interior well whenever a residual is needed.", "It requires the mask to be disabled, since the new well is outside the original hull."]'::jsonb, 1, 'That is exactly what leave-one-out cannot offer. Its weakness is the opposite one: there is one of it, it cost a well, and it is retrospective.'),
  ('mapping', 'advanced', 'final', null, 9, 'What is the six-well prediction at Ekene-7 and what must be true when it is read?', '["1549 m, read after the well has been added so that the map honours the pick.", "1547.105224609375 m, read on the seven-well map at the prospect.", "1543.3271484375 m, read before Ekene-7 joins the control set.", "1555.8438720703125 m, read on the map with Ekene-6 withheld."]'::jsonb, 2, 'It is the only state in which that number exists. The other three options are the seven-well P-1 reading, the pick itself, and the Ekene-6 leave-one-out prediction.'),
  ('mapping', 'advanced', 'final', null, 10, 'The six-well map places P-1 at 1542.62 m and Ekene-7, 141 m away, at 1543.33 m. What did the blind test do to that picture?', '["It confirmed it, since the pick of 1549 m is within the 10 m contour interval of both.", "It left it unchanged, since a single pick cannot alter the relationship between two mapped values.", "It contradicted the flatness: the pick came in 5.67 m below the map.", "It made P-1 the shallower of the two by a larger margin than the map showed."]'::jsonb, 2, 'A difference of 0.71 m over 141 m was a very flat claim, and the well found the horizon well below it. P-1 then moved 4.49 m deeper when the pick joined the control.'),
  ('mapping', 'advanced', 'final', null, 11, 'Why do the two residuals having opposite signs rule out a correction to the map?', '["Because a shift removing their mean improves one location and worsens the other.", "Because a correction can only be applied where the residual exceeds the contour interval.", "Because the mean of two opposite-signed residuals is not statistically significant.", "Because a correction would move the map away from the wells it honours exactly."]'::jsonb, 0, 'Shifting down by 2.09 m makes Ekene-6 read 11.93 m and Ekene-7 minus 3.58 m, with the sum of absolute errors unchanged. A shift is only worth applying when the residuals share a sign.'),
  ('mapping', 'advanced', 'final', null, 12, 'Which cause would produce residuals of the same sign at two interior locations?', '["Local structure at a scale shorter than the well spacing.", "A datum error, a pick bias, or a trend the interpolator flattens.", "A frame that moves between the two validation runs.", "A mask that reaches one location and not the other."]'::jsonb, 1, 'Each has a specific and cheap chase that needs no new data: check the datums, re-pick blind, or de-trend before gridding. On Ekene the signs are opposite, so none of them applies.'),
  ('mapping', 'advanced', 'final', null, 13, 'With Ekene-7 in the control, what is the live node count and what would a different answer mean?', '["201, and a different answer means an exterior well was modelled.", "260, and a smaller answer means the extrapolation limit was reduced.", "201, and a different answer means the frame was rederived from seven wells.", "202, one node per control point plus the original count."]'::jsonb, 0, 'Ekene-7 is interior, so it adds no hull area and every node within 800 m of it was already reachable. The field is graded exactly.'),
  ('mapping', 'advanced', 'final', null, 14, 'The seven-well leave-one-out at Ekene-7 returns exactly minus 5.6728515625 m. Why is that worth running?', '["Because it is a second independent estimate of the same residual.", "It tests the frame, settings, sampling and removal logic against a known answer.", "Because it is the only way to obtain a residual at an exterior well.", "Because it updates the blind residual for the improved seven-well map."]'::jsonb, 1, 'Removing Ekene-7 restores the original six wells, so the identity must hold. A disagreement of any size means something in the pipeline differs between the two paths.'),
  ('mapping', 'advanced', 'final', null, 15, 'Ekene-6''s leave-one-out residual changes by 0.028 m when Ekene-7 joins the control set. What is the lesson?', '["That a well''s influence falls off quickly, so an appraisal well de-risks locally.", "That the two runs are effectively identical, so the seven-well exercise adds nothing.", "That the new pick was inconsistent with the surrounding wells and should be re-examined.", "That the map is now well constrained at Ekene-6, since the residual barely moved."]'::jsonb, 0, 'Ekene-7''s pick of 1549 m is close to what the surrounding wells already implied at 500 m away. The residual is still nearly 10 m, so nothing about Ekene-6 has been fixed.'),
  ('mapping', 'advanced', 'final', null, 16, 'Why is the largest change between the six-well and seven-well maps exactly the blind residual?', '["Because the difference map is normalised to its largest value, which is at the new well.", "Because an exact interpolator forces the surface through the new point.", "Because the mask blanks every node where the change would have been larger.", "Because the two maps share a frame, which bounds the change by the node spacing."]'::jsonb, 1, 'The map said 1543.3271484375 m and now says 1549 m at (1500, 1500). The change a new well will cause at its own location is knowable the moment the pick arrives.'),
  ('mapping', 'advanced', 'final', null, 17, 'The mean absolute change over the 201 live nodes is 1.92 m. What does that number license you to say?', '["That the seven-well map is accurate to about two metres.", "That one well changed the average node by nearly two metres on a 49 m field.", "That the difference between the two maps is within the 5 m contour interval and therefore not material.", "That the spline redistributed its bending energy evenly across the map."]'::jsonb, 1, 'About four percent of the field''s 49 m of relief was rearranged by a single fact arriving. It is a measurement rather than an estimate.'),
  ('mapping', 'advanced', 'final', null, 18, 'What happened to the crest overshoot when Ekene-7 was added?', '["It grew from 1.2819 m to 1.9 m, because a seventh control point adds bending.", "It fell from 1.2819 m to 0.2944 m, a reduction of 77 percent.", "It vanished, because the crest now sits on Ekene-3''s own node.", "It was unchanged, because overshoot is a property of the interpolator."]'::jsonb, 1, 'The overshoot is measured against the shallowest pick of 1541 m at Ekene-3. It shrank because Ekene-7 put a measurement into the gap the spline was filling with curvature.'),
  ('mapping', 'advanced', 'final', null, 19, 'What is the general result about spline overshoot that this tier can state and the Associate tier could not?', '["That it is an artefact of the contour interval and disappears when the interval is fixed by hand.", "That it is an information deficit, which shrinks when control is added near it.", "That it is removed by refining the cell size once the control is dense enough.", "That it is proportional to the range of the control values and therefore predictable."]'::jsonb, 1, 'The Associate tier showed that neither refinement nor a wider mask removes it. It has an immediate practical use: the well that most reduces the uncertainty is one between the crest and its nearest control.'),
  ('mapping', 'advanced', 'final', null, 20, 'P-1 moved 4.4854 m deeper when Ekene-7 joined the control. What fraction of the change at Ekene-7''s own node is that?', '["79 percent, because P-1 is only 141 m from the new well.", "50 percent, since influence halves over the first cell of separation.", "100 percent, because both locations are interior to the same hull.", "26 percent, which is the reduction in the oil column at a 1560 m contact."]'::jsonb, 0, 'The influence of a new control point is strongest at its own location and falls off with distance. P-1 goes from 2.90 m below the crest to 6.40 m below it.'),
  ('mapping', 'advanced', 'final', null, 21, 'Why does the jackknife escape the hull limitation that stopped leave-one-out?', '["It samples P-1, which stays inside the mask under every removal.", "It removes wells from the display rather than from the control set.", "It uses the seven-well hull, which contains every location of interest.", "It relaxes the hull test, which is acceptable because no residual is reported."]'::jsonb, 0, 'The hull limitation applies to the location being sampled. Removing Ekene-1 puts Ekene-1''s own site outside the mask and leaves P-1 comfortably inside it.'),
  ('mapping', 'advanced', 'final', null, 22, 'What is the jackknife spread at P-1 and how was it obtained?', '["7.77 m, the range of six five-well maps sampled at a fixed location.", "7.77 m, the range of the six leave-one-out residuals at the wells.", "3.12 m, the standard deviation of the six values, which is the spread proper.", "4.49 m, the movement caused by adding the seventh well."]'::jsonb, 0, 'The values run from 1541.939208984375 m without Ekene-2 to 1549.7083740234375 m without Ekene-6. The standard deviation of 3.12 m is a separate summary of the same six numbers.'),
  ('mapping', 'advanced', 'final', null, 23, 'Which two wells dominate the jackknife at P-1, and for what different reasons?', '["Ekene-6 and Ekene-3, one the nearest control and one the shallowest pick.", "Ekene-2 and Ekene-4, the two wells that leave five hull vertices when removed.", "Ekene-1 and Ekene-5, the two wells whose removal changes the derived frame.", "Ekene-6 and Ekene-4, one the nearest control and one the deep northeast anchor."]'::jsonb, 3, 'Ekene-6 moves P-1 by 7.09 m from 361 m away and Ekene-4 by 4.59 m from 1345 m away. The dominant wells are the nearest ones plus any well anchoring an extreme.'),
  ('mapping', 'advanced', 'final', null, 24, 'Two removals make P-1 shallower and four make it deeper. What does that mixture mean?', '["That the six-well answer is biased shallow and should be moved to the jackknife mean.", "That two of the six runs used a different frame and should be rerun.", "That the direction depends on which way the removed well was pulling.", "That the spread should be quoted asymmetrically about the mean of the six."]'::jsonb, 2, 'It is not a bias. The asymmetry of the range about the six-well answer is why it should not be halved into a plus-or-minus.'),
  ('mapping', 'advanced', 'final', null, 25, 'Why is the jackknife spread a pessimistic estimate?', '["Because it is quoted as a full range rather than as a standard deviation.", "Because it is computed before the mask is applied, so edge nodes inflate it.", "Because it includes the effect of removing wells that are not near the location sampled.", "Because every value in it comes from a five-well map, worse than the map in use."]'::jsonb, 3, 'That is the same direction of bias leave-one-out carries, and pessimistic is the right way for an error estimate to be wrong.'),
  ('mapping', 'advanced', 'final', null, 26, 'The seven-well map reads 1547.11 m at P-1, inside the jackknife range at 66.5 percent of its width. What does that NOT license?', '["That the range was a usable prior for the effect of new control on this field.", "That the estimate was available before drilling, which is what makes it worth computing.", "That the range is a probability distribution, with a 66.5 percent chance of landing below.", "That the uncertainty estimate survived being checked, which most never are."]'::jsonb, 2, 'Six values are not a distribution and one successful test is not a validated method. The result is a single successful check and should be stated as such.'),
  ('mapping', 'advanced', 'final', null, 27, 'Which of the five things the jackknife spread is not covers pick, datum and method uncertainty?', '["That it is not a confidence interval.", "That it is not symmetric.", "That it is not the total uncertainty.", "That it is not transferable to another location."]'::jsonb, 2, 'It measures sensitivity to which wells are present and holds the picks, the datum, the depth conversion and the method fixed. On sparse control it is usually the largest term in the budget, which is why it is worth computing first.'),
  ('mapping', 'advanced', 'final', null, 28, 'A colleague writes: depth at P-1 is 1542.6 plus or minus 3.9 m at 90 percent confidence (jackknife). How many errors are in that sentence?', '["One, the confidence claim.", "Two, the confidence claim and the symmetry.", "Three, the symmetry, the probability, and the missing statement of scope.", "None, provided the jackknife was computed at that location."]'::jsonb, 2, 'The precision of 1542.6 m is reasonable and the attribution to the jackknife is correct, so the sentence is three edits away from being usable.'),
  ('mapping', 'advanced', 'final', null, 29, 'Why would a jackknife spread computed at P-1 not apply at a location near a well?', '["Because near a well the spread approaches zero, the surface being pinned.", "Because near a well the mask changes under each removal, so the runs are not comparable.", "Because near a well the spread is dominated by pick uncertainty instead.", "Because near a well the sampled value is read at a node rather than interpolated."]'::jsonb, 0, 'It is a per-location quantity and one number quoted for a whole map means somebody computed it once and reused it.'),
  ('mapping', 'advanced', 'final', null, 30, 'Which four elements belong in a reported mapped depth?', '["The number, the contour interval, the live node count and the mapped area.", "The number to twelve digits, the frame, the mask setting and the well count.", "The number, the crest, the deepest value and the map mean.", "The number, the conditions, the control sensitivity, and the demonstrated errors."]'::jsonb, 3, 'Quoting 1542.6 m rather than 1542.619873046875 m loses nothing and claims nothing false. The residuals are quoted individually with their signs and never averaged.'),
  ('mapping', 'advanced', 'final', null, 31, 'What does a volumetrics engineer do differently on receiving the four-element version rather than a bare depth?', '["Runs the volume at 1542 m and at 1550 m and sees how much the answer moves.", "Regrids the surface at a finer cell to reduce the quoted spread.", "Applies the mean residual as a correction before computing the column.", "Uses the jackknife mean of 1544.66 m as the central case."]'::jsonb, 0, 'At a 1560 m contact that is a 17.4 m column against a 10 m column, a 43 percent change. Nothing about the map improved; what improved is that the number arrives with enough attached to be used properly.'),
  ('mapping', 'advanced', 'final', null, 32, 'Which step protects against the most avoidable loss in the whole validation workflow?', '["Freezing the map before any run, which protects the residuals from the frame.", "Identifying the interior wells, which protects against a table of extrapolations.", "Recording the current map''s prediction at a planned well before it is drilled.", "Reporting residuals individually, which protects the reader."]'::jsonb, 2, 'A blind test destroyed by regridding before the prediction was written down cannot be recovered. On this field the payoff was a residual of minus 5.67 m, a third of the tier''s evidence.'),
  ('mapping', 'advanced', 'final', null, 33, 'Which of the three interpretation checks would flag a report quoting a root mean square over two residuals?', '["Whether the residuals share a sign.", "Whether the withheld well was actually removed from the control.", "Whether a jackknife spread is being quoted for more than one location.", "Whether a summary is quoted over fewer than about five residuals."]'::jsonb, 3, 'A mean over two is cancellation and a root mean square over two is dressing up. Quote them individually.'),
  ('mapping', 'advanced', 'final', null, 34, 'Which failed check is a finding rather than a fault?', '["A frame that moves between runs.", "A residual of exactly zero at a withheld well.", "A prediction returned where the hull test should have blanked it.", "Two residuals with opposite signs."]'::jsonb, 3, 'The correct response is to write them down as they are. A moving frame is a silent bias fixed by rebuilding the runs, a zero residual is a procedural error, and an extrapolated prediction is not a validation at all.'),
  ('mapping', 'advanced', 'final', null, 35, 'Which capstone field would a learner lose by reporting the cross-validatable count as 6?', '["That field alone, since the count is graded exactly.", "That field and the leave-one-out residual, since both come from the same runs.", "All six, since the count determines which panel states the others are read in.", "None, since 6 is within the tolerance of a count field."]'::jsonb, 0, 'Reporting 6 requires having disabled the hull mask, and the field carries no tolerance. The other five fields are read in their own panel states.'),
  ('mapping', 'advanced', 'final', null, 36, 'Which self-consistency check confirms that the crest was read in the right panel state?', '["The crest must sit at the same node as the six-well crest.", "The crest must be shallower than the shallowest pick on the field.", "The crest must lie within one contour interval of the six-well crest.", "The seven-well crest must be deeper than the six-well crest."]'::jsonb, 3, '1540.7056 m against 1539.7181 m, because the new well constrains an overshoot. A seven-well crest that came out shallower means the wrong state was read.'),
  ('mapping', 'advanced', 'final', null, 37, 'What can mapping not guarantee, however carefully the ladder is followed?', '["That a surface honours every control point exactly.", "That every blank is a place the control does not reach.", "That six wells resolve structure shorter than their spacing.", "That a map can be rebuilt by anyone from the picks, the frame and the settings."]'::jsonb, 2, 'Both residuals in this tier are that limitation measured twice, and no interpolator removes it. Mapping also cannot tell you whether the picks are right, which belongs to well correlation.'),
  ('mapping', 'advanced', 'final', null, 38, 'Where does the cross-validatable count stop being a small number in practice?', '["When the extrapolation limit is widened enough to cover the whole hull.", "When the field has more than ten wells, whatever their arrangement.", "When the cell size is refined so that every well lands on a node.", "When depth-converted seismic picks are used as control alongside the wells."]'::jsonb, 3, 'Seismic control turns most wells into interior points and makes cross validation genuinely statistical. A six-well exercise is a teaching case rather than a template.'),
  ('mapping', 'advanced', 'final', null, 39, 'Which trade did this tier quantify for well planning?', '["Interior wells improve the contour interval; exterior wells improve the mask.", "Interior wells buy coverage; exterior wells buy validatability.", "Interior wells reduce the jackknife spread everywhere; exterior wells reduce it near the edges.", "Interior wells buy validatability; exterior wells buy coverage."]'::jsonb, 3, 'Ekene-7 left the live node count at 201 and took the cross-validatable count from 1 to 2. A well at (3000, 1000) would have done the opposite.'),
  ('mapping', 'advanced', 'final', null, 40, 'Which three tiers of the Mapping ladder did what, in order?', '["Grid a surface; refine the grid; contour it for reporting.", "Build a surface; validate it; combine it with a second surface.", "Pick horizons; grid them; convert them to depth.", "Build a surface; combine surfaces; measure what that is worth."]'::jsonb, 3, 'The Associate tier builds and reads one masked, contoured surface, the Professional tier grids a second on the same frame and combines them, and the Expert tier measures predictive skill by withholding control.'),
  ('mapping', 'advanced', 'final', null, 41, 'Which single sentence justifies the jackknife to a colleague who thinks it is extra work?', '["It removes the spline overshoot that the tiers below could only describe.", "It replaces the mean residual, which cannot be computed from two validation tests.", "It is the only uncertainty estimate that carries a probability a reader can act on.", "Six regridding runs turn a number a reader over-trusts into one they can use."]'::jsonb, 3, 'On this field the range was 7.77 m at the prospect and it correctly contained the 4.49 m the answer actually moved when the next well was drilled.'),
  ('mapping', 'advanced', 'final', null, 42, 'A map honours all six wells, its contours look geological and its residuals at the control are zero. What has been established?', '["That the picks are mutually consistent, since an inconsistent set could not be honoured exactly by a smooth surface.", "That the map is a good predictor at locations between the wells, since it agrees with every measurement available.", "That the interpolation is exact, the fit is smooth and the software works.", "That the map is at least as accurate as its contour interval, which is 10 m on this field."]'::jsonb, 2, 'All three are true of any exact interpolator on any dataset, including one made of random numbers. Predictive skill has to be measured by withholding data.');
